INSERT INTO `acore_string` (`entry`, `content_default`, `locale_ruRU`) VALUES
(30098, '|cff4CFF00[Guild System]|r This server is running guild system.', '|cff4CFF00[Система гильдии]|r Этот сервер использует систему гильдии.'),
(30099, '|cff4CFF00[Guild System]|r The guild receives {} exp.', '|cff4CFF00[Система гильдии]|r Гильдия получает {} опыта.'),
(30100, '|cff4CFF00[Guild System]|r Congratulations, the guild has reached a new level {} !', '|cff4CFF00[Система гильдии]|r Поздравляем, гильдия получила новый уровень {} !'),
(30101, '| Experience: {} / {}\n| Level: {}\n| To next level: {}', '| Опыт: {} / {}\n| Уровень: {}\n| До следующего уровня: {}'),
(30102, '| Guild Master: {}', '| Мастер гильдии: {}'),
(30103, '|cff4CFF00[Guild System]|r You receive {} guild reputation.', '|cff4CFF00[Система гильдии]|r Вы получаете {} репутации гильдии.'),
(30104, '| Guild reputation: {} ({})\n| Weekly reputation: {} / {}', '| Репутация гильдии: {} ({})\n| Недельная репутация: {} / {}'),
(30105, '|cff4CFF00[Guild System]|r You must be in a guild to use this vendor.', '|cff4CFF00[Система гильдии]|r Вы должны состоять в гильдии, чтобы пользоваться этим торговцем.'),
(30106, '|cff4CFF00[Guild System]|r You cannot purchase that reward.', '|cff4CFF00[Система гильдии]|r Вы не можете купить эту награду.');
